style.css:
body {
    /* The browser replaces the [[key]] with the uploaded image's URL */
    background-image: url(https://i.pinimg.com/736x/00/e5/ca/00e5ca0020c1c0a9827b5ac83d1cc6ae.jpg) !important;
    
    /* Standard settings to make the art look good as a background */
    background-size: cover;        /* Fills the screen without stretching */
    background-position: center;  /* Keeps Shelly centered */
    background-attachment: fixed;  /* Keeps the art from scrolling with the page */
    background-repeat: no-repeat;  /* Prevents the image from tiling */
}
